'use client';

/**
 * Create / edit a contact type (PG-205, ADR-080). Save is disabled until the draft
 * differs from its snapshot, while saving, and while a conflict is shown (empty or
 * duplicate name). A server CONFLICT on the name is shown under the field
 * (`role="alert"`) and the field is focused. The key is generated by the server on
 * create and never changes; it is shown read-only when editing.
 */
import { useEffect, useRef, useState } from 'react';
import {
  Button,
  Checkbox,
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  Input,
  Label,
  RadioGroup,
  RadioGroupItem,
  Switch,
} from '@intelliflow/ui';
import {
  CONTACT_STATUSES,
  CONTACT_TYPE_LIMITS,
  CONTACT_TYPE_REQUIRED_FIELD_KEYS,
  type ContactStatus,
  type ContactTypeOwnerDefault,
  type ContactTypeRequiredFieldKey,
} from '@intelliflow/domain';
import {
  CONTACT_TYPE_COLOR_TOKENS,
  findDuplicateContactTypeName,
  type ContactTypeDto,
} from '@intelliflow/validators';
import {
  CONTACT_TYPE_COLOR_LABELS,
  contactTypeSwatchClass,
  toContactTypeColorToken,
  type ContactTypeColorToken,
} from '@/components/contacts/contact-type-colors';
import { DefaultTagPicker, type DefaultTagOption } from './DefaultTagPicker';

export const STATUS_LABELS: Record<ContactStatus, string> = {
  ACTIVE: 'Active',
  INACTIVE: 'Inactive',
  PROSPECT: 'Prospect',
  CUSTOMER: 'Customer',
  FORMER_CUSTOMER: 'Former customer',
};

export const REQUIRED_FIELD_LABELS: Record<ContactTypeRequiredFieldKey, string> = {
  phone: 'Phone',
  company: 'Company',
  title: 'Job title',
  department: 'Department',
  accountId: 'Account',
};

const OWNER_LABELS: Record<ContactTypeOwnerDefault, string> = {
  CREATOR: 'Creator',
  ACCOUNT_OWNER: 'Account owner',
};

export interface ContactTypeDraft {
  name: string;
  colorToken: ContactTypeColorToken;
  isActive: boolean;
  defaultStatus: ContactStatus | '';
  defaultDepartment: string;
  defaultOwner: ContactTypeOwnerDefault;
  requiredFields: ContactTypeRequiredFieldKey[];
  defaultTagIds: string[];
}

export interface ContactTypeSaveInput {
  name: string;
  colorToken: ContactTypeColorToken;
  isActive: boolean;
  defaultStatus: ContactStatus | null;
  defaultDepartment: string | null;
  defaultOwner: ContactTypeOwnerDefault;
  requiredFields: ContactTypeRequiredFieldKey[];
  defaultTagIds: string[];
}

/**
 * `ok: false` keeps the dialog open; an `error` (a name conflict) is shown under the
 * name field. Other failures are reported by the caller (toast).
 */
export type ContactTypeSaveResult = { ok: true } | { ok: false; error?: string };

export function draftFromContactType(type: ContactTypeDto | null): ContactTypeDraft {
  if (!type) {
    return {
      name: '',
      colorToken: 'slate',
      isActive: true,
      defaultStatus: '',
      defaultDepartment: '',
      defaultOwner: 'CREATOR',
      requiredFields: [],
      defaultTagIds: [],
    };
  }
  return {
    name: type.name,
    colorToken: toContactTypeColorToken(type.colorToken),
    isActive: type.isActive,
    defaultStatus: type.defaultStatus ?? '',
    defaultDepartment: type.defaultDepartment ?? '',
    defaultOwner: type.defaultOwner,
    requiredFields: [...type.requiredFields],
    defaultTagIds: type.defaultTags.map((tag) => tag.id),
  };
}

/** Comparable form of a draft. */
function fingerprint(draft: ContactTypeDraft): string {
  return JSON.stringify({
    ...draft,
    name: draft.name.trim(),
    defaultDepartment: draft.defaultDepartment.trim(),
    requiredFields: [...draft.requiredFields].sort((a, b) => a.localeCompare(b)),
    defaultTagIds: [...draft.defaultTagIds].sort((a, b) => a.localeCompare(b)),
  });
}

export function toSaveInput(draft: ContactTypeDraft): ContactTypeSaveInput {
  return {
    name: draft.name.trim(),
    colorToken: draft.colorToken,
    isActive: draft.isActive,
    defaultStatus: draft.defaultStatus === '' ? null : draft.defaultStatus,
    defaultDepartment: draft.defaultDepartment.trim() || null,
    defaultOwner: draft.defaultOwner,
    // Field order follows the checkbox order so equal choices save equally.
    requiredFields: CONTACT_TYPE_REQUIRED_FIELD_KEYS.filter((key) =>
      draft.requiredFields.includes(key)
    ),
    defaultTagIds: draft.defaultTagIds,
  };
}

export interface ContactTypeDialogProps {
  open: boolean;
  /** null = create. */
  contactType: ContactTypeDto | null;
  /** All types, for the duplicate-name check. */
  existing: readonly { id: string; name: string }[];
  /** The tenant's contact tags, for the default-tag picker. */
  tags: readonly DefaultTagOption[];
  isSaving: boolean;
  onSave: (input: ContactTypeSaveInput) => Promise<ContactTypeSaveResult>;
  onClose: () => void;
}

const FIELD_CLASS =
  'flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2';

export function ContactTypeDialog({
  open,
  contactType,
  existing,
  tags,
  isSaving,
  onSave,
  onClose,
}: Readonly<ContactTypeDialogProps>) {
  const [snapshot, setSnapshot] = useState(() => draftFromContactType(contactType));
  const [draft, setDraft] = useState(snapshot);
  const [serverError, setServerError] = useState<string | null>(null);
  const nameRef = useRef<HTMLInputElement>(null);

  // Reset whenever the dialog opens for a (possibly different) type.
  useEffect(() => {
    if (!open) return;
    const next = draftFromContactType(contactType);
    setSnapshot(next);
    setDraft(next);
    setServerError(null);
  }, [open, contactType]);

  const set = <K extends keyof ContactTypeDraft>(key: K, value: ContactTypeDraft[K]) => {
    setDraft((current) => ({ ...current, [key]: value }));
    if (key === 'name') setServerError(null);
  };

  // The stored default tags: kept selectable even if a tag was deactivated since.
  const keptTagIds = snapshot.defaultTagIds;
  const trimmedName = draft.name.trim();
  const duplicateName = findDuplicateContactTypeName(existing, trimmedName, contactType?.id);
  const isDefault = contactType?.isDefault ?? false;
  const hasConflict = !trimmedName || duplicateName !== null;
  const isDirty = fingerprint(draft) !== fingerprint(snapshot);
  const nameError =
    serverError ??
    (duplicateName ? `A contact type named “${duplicateName}” already exists.` : null);

  const toggleRequired = (key: ContactTypeRequiredFieldKey, checked: boolean) =>
    set(
      'requiredFields',
      checked ? [...draft.requiredFields, key] : draft.requiredFields.filter((k) => k !== key)
    );

  const save = async () => {
    const result = await onSave(toSaveInput(draft));
    if (!result.ok) {
      if (result.error) {
        setServerError(result.error);
        nameRef.current?.focus();
      }
      return;
    }
    onClose();
  };

  return (
    <Dialog open={open} onOpenChange={(next) => (next ? null : onClose())}>
      <DialogContent className="sm:max-w-2xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{contactType ? `Edit ${contactType.name}` : 'New Contact Type'}</DialogTitle>
          <DialogDescription>
            These defaults are applied when a contact of this type is created. Existing contacts
            keep their values.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-5">
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <Label htmlFor="contact-type-name">Name</Label>
              <Input
                id="contact-type-name"
                ref={nameRef}
                value={draft.name}
                maxLength={CONTACT_TYPE_LIMITS.maxNameLength}
                onChange={(e) => set('name', e.target.value)}
                aria-invalid={nameError ? true : undefined}
                aria-describedby={nameError ? 'contact-type-name-error' : undefined}
              />
              {nameError && (
                <p
                  id="contact-type-name-error"
                  role="alert"
                  className="text-xs text-red-700 dark:text-red-300"
                >
                  {nameError}
                </p>
              )}
            </div>
            {contactType && (
              <div className="space-y-1.5">
                <span className="text-sm font-medium leading-none" id="contact-type-key-label">
                  Key
                </span>
                <p
                  className="flex h-10 items-center rounded-md border border-border bg-muted px-3 font-mono text-sm text-muted-foreground"
                  aria-labelledby="contact-type-key-label"
                >
                  {contactType.key}
                </p>
                <p className="text-xs text-muted-foreground">
                  Stored on contacts; it never changes when you rename the type.
                </p>
              </div>
            )}
          </div>

          <fieldset className="space-y-2">
            <legend id="contact-type-colour-legend" className="text-sm font-medium text-foreground">
              Colour
            </legend>
            <RadioGroup
              aria-labelledby="contact-type-colour-legend"
              value={draft.colorToken}
              onValueChange={(value) => set('colorToken', toContactTypeColorToken(value))}
              className="grid grid-cols-2 sm:grid-cols-4 gap-2"
            >
              {CONTACT_TYPE_COLOR_TOKENS.map((token) => (
                <label
                  key={token}
                  htmlFor={`contact-type-color-${token}`}
                  className="flex min-h-11 cursor-pointer items-center gap-2 rounded-lg border border-border px-3 py-2 has-[[data-state=checked]]:ring-2 has-[[data-state=checked]]:ring-primary"
                >
                  <RadioGroupItem id={`contact-type-color-${token}`} value={token} />
                  <span
                    className={`inline-block h-4 w-4 rounded-full ${contactTypeSwatchClass(token)}`}
                    aria-hidden="true"
                  />
                  <span className="text-sm">{CONTACT_TYPE_COLOR_LABELS[token]}</span>
                  {draft.colorToken === token && (
                    <span
                      className="material-symbols-outlined ml-auto text-[16px] text-primary"
                      aria-hidden="true"
                      data-testid="swatch-check"
                    >
                      check
                    </span>
                  )}
                </label>
              ))}
            </RadioGroup>
          </fieldset>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div className="space-y-1.5">
              <Label htmlFor="contact-type-status">Default status</Label>
              <select
                id="contact-type-status"
                className={FIELD_CLASS}
                value={draft.defaultStatus}
                onChange={(e) => set('defaultStatus', e.target.value as ContactStatus | '')}
                aria-describedby="contact-type-status-help"
              >
                <option value="">No default</option>
                {CONTACT_STATUSES.map((status) => (
                  <option key={status} value={status}>
                    {STATUS_LABELS[status]}
                  </option>
                ))}
              </select>
              <p id="contact-type-status-help" className="text-xs text-muted-foreground">
                Used when the person creating the contact leaves status unset.
              </p>
            </div>
            <div className="space-y-1.5">
              <Label htmlFor="contact-type-department">Default department</Label>
              <Input
                id="contact-type-department"
                value={draft.defaultDepartment}
                maxLength={CONTACT_TYPE_LIMITS.maxDepartmentLength}
                placeholder="e.g. Procurement"
                onChange={(e) => set('defaultDepartment', e.target.value)}
              />
            </div>
          </div>

          <fieldset className="space-y-2" aria-describedby="contact-type-owner-help">
            <legend id="contact-type-owner-legend" className="text-sm font-medium text-foreground">
              Owner of new contacts
            </legend>
            <p id="contact-type-owner-help" className="text-xs text-muted-foreground">
              Account owner uses the owner of the linked account; it falls back to the creator when
              no account is linked or that owner is no longer in the workspace.
            </p>
            <RadioGroup
              aria-labelledby="contact-type-owner-legend"
              value={draft.defaultOwner}
              onValueChange={(value) =>
                set('defaultOwner', value === 'ACCOUNT_OWNER' ? 'ACCOUNT_OWNER' : 'CREATOR')
              }
              className="flex flex-wrap gap-x-6 gap-y-2"
            >
              {(Object.keys(OWNER_LABELS) as ContactTypeOwnerDefault[]).map((owner) => (
                <div key={owner} className="flex min-h-11 items-center gap-2">
                  <RadioGroupItem id={`contact-type-owner-${owner}`} value={owner} />
                  <Label htmlFor={`contact-type-owner-${owner}`}>{OWNER_LABELS[owner]}</Label>
                </div>
              ))}
            </RadioGroup>
          </fieldset>

          <fieldset className="space-y-2" aria-describedby="contact-type-required-help">
            <legend className="text-sm font-medium text-foreground">
              Required when creating a contact
            </legend>
            <p id="contact-type-required-help" className="text-xs text-muted-foreground">
              Added on top of the Contact Settings required fields, and checked again when a contact
              is changed to this type.
            </p>
            <div className="flex flex-wrap gap-x-6 gap-y-2">
              {CONTACT_TYPE_REQUIRED_FIELD_KEYS.map((key) => (
                <div key={key} className="flex min-h-11 items-center gap-2">
                  <Checkbox
                    id={`contact-type-required-${key}`}
                    checked={draft.requiredFields.includes(key)}
                    onCheckedChange={(checked) => toggleRequired(key, checked === true)}
                  />
                  <Label htmlFor={`contact-type-required-${key}`}>
                    {REQUIRED_FIELD_LABELS[key]}
                  </Label>
                </div>
              ))}
            </div>
          </fieldset>

          <DefaultTagPicker
            tags={tags}
            value={draft.defaultTagIds}
            keptIds={keptTagIds}
            onChange={(next) => set('defaultTagIds', next)}
          />

          <div className="flex min-h-11 items-center justify-between gap-3">
            <Label htmlFor="contact-type-active">Active</Label>
            <Switch
              id="contact-type-active"
              checked={draft.isActive}
              onCheckedChange={(checked) => set('isActive', checked)}
              disabled={isDefault && draft.isActive}
              aria-describedby="contact-type-active-help"
            />
          </div>
          <p id="contact-type-active-help" className="text-xs text-muted-foreground -mt-3">
            {isDefault
              ? 'The default contact type must stay active.'
              : 'Inactive types are hidden from the contact forms; existing contacts keep them.'}
          </p>
        </div>

        <DialogFooter>
          <Button type="button" variant="outline" onClick={onClose}>
            Cancel
          </Button>
          <Button type="button" onClick={save} disabled={!isDirty || isSaving || hasConflict}>
            {isSaving ? 'Saving…' : 'Save'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
